using System.Linq.Expressions;

namespace FreightTrack.Web.Models;

public class Shipment
{
    public int Id { get; set; }

    /// <summary>Generated by ShipmentService, e.g. FT-2026-000123. Never edited after creation.</summary>
    public string TrackingNumber { get; set; } = string.Empty;

    public int CustomerId { get; set; }
    public Customer Customer { get; set; } = null!;   // null! = "EF will fill this in, trust me"

    public string Origin { get; set; } = string.Empty;
    public string Destination { get; set; } = string.Empty;
    public ShipmentMode Mode { get; set; }
    public decimal WeightKg { get; set; }             // decimal (not double) for exact values, like BigDecimal
    public decimal DeclaredValue { get; set; }

    /// <summary>Always equals the Status of the latest ShipmentStatusUpdate (kept in sync by ShipmentService).</summary>
    public ShipmentStatus CurrentStatus { get; set; } = ShipmentStatus.Booked;

    public DateTime BookedDate { get; set; }
    public DateTime ExpectedDeliveryDate { get; set; }
    public DateTime? DeliveredDate { get; set; }

    public List<ShipmentStatusUpdate> StatusUpdates { get; set; } = new();

    /// <summary>
    /// The "late" rule as an Expression, so EF Core can translate it into a SQL WHERE clause.
    /// A normal C# method can't be translated to SQL; an expression tree can.
    /// </summary>
    public static Expression<Func<Shipment, bool>> IsLateExpression(DateTime today) =>
        s => s.CurrentStatus != ShipmentStatus.Delivered && s.ExpectedDeliveryDate < today.Date;

    /// <summary>The same rule for an object already in memory.</summary>
    public bool IsLate(DateTime today) =>
        CurrentStatus != ShipmentStatus.Delivered && ExpectedDeliveryDate.Date < today.Date;

    public int DaysOverdue(DateTime today) =>
        IsLate(today) ? (today.Date - ExpectedDeliveryDate.Date).Days : 0;

    /// <summary>
    /// True when origin and destination are in different countries (locations are stored as
    /// "City, Country"). Only cross-border shipments go through customs, so the app leaves the
    /// "At customs" step out of a domestic shipment's journey.
    /// [NotMapped] = calculated in C#, not a database column.
    /// </summary>
    [System.ComponentModel.DataAnnotations.Schema.NotMapped]
    public bool CrossesBorder =>
        !string.Equals(CountryOf(Origin), CountryOf(Destination), StringComparison.OrdinalIgnoreCase);

    public static string CountryOf(string place)
    {
        var comma = place.LastIndexOf(',');
        return (comma >= 0 ? place[(comma + 1)..] : place).Trim();
    }
}
